### Ingest CLI codact failures
# @name postCliCodactFailures
POST {{host}}/api/v3/cli/codact_failures
Authorization: Bearer {{token}}
x-user-api-key: {{x-user-api-key}}
Content-Type: application/json
Accept: application/json

{
  "failure_type": "wrong_tool_slug",
  "tool_info": {
    "toolkit": "github",
    "tool": {
      "slug": "GITHUB_CREATE_AN_ISSUE",
      "version": "2026.03.23"
    }
  },
  "ctx": {
    "invalid_tool_slug": "GITHUB_MAKE_ISSUE"
  },
  "session": {
    "id": "sess_123",
    "source": "cli"
  },
  "request_id": "req_123"
}

## Responses
# 200
# Description: CLI codact failure accepted and stored.
# Content-Type: application/json
# 400
# Description: Bad request.
# Content-Type: application/json
# 401
# Description: Unauthorized. A valid user API key is required.
# Content-Type: application/json
# 500
# Description: Internal server error.
# Content-Type: application/json

